def UpsertPermission(self, user_link, permission, options=None):
        """Upserts a permission for a user.

        :param str user_link:
            The link to the user entity.
        :param dict permission:
            The Azure Cosmos user permission to upsert.
        :param dict options:
            The request options for the request.

        :return:
            The upserted permission.
        :rtype:
            dict

        """
        if options is None:
            options = {}

        if permission is None:
            raise ValueError("permission must be set")

        if not isinstance(permission, dict):
            raise TypeError("permission must be a dict")

        if not isinstance(user_link, six.string_types):
            raise TypeError("user_link must be a string")

        if not user_link:
            raise ValueError("user_link must be set")

        if not isinstance(options, dict):
            raise TypeError("options must be a dict")

        request_options = {
            'offerThroughput': options.get('offer_throughput')
        }

        return self.client_connection.UpsertPermission(
            user_link, permission, request_options)

